(function(root){
  'use strict';
  function open({db,source={},copy=false,onSave}){
    const C=root.WildsCharmRules,dialog=document.querySelector('#editor'),host=document.querySelector('#editor-content');
    const $=s=>host.querySelector(s),$$=s=>[...host.querySelectorAll(s)],esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
    const option=(v,label,current)=>`<option value="${esc(v)}" ${String(v)===String(current)?'selected':''}>${esc(label)}</option>`;
    const skills=db.skills.filter(s=>!['set','group'].includes(s.kind)).sort((a,b)=>a.name.localeCompare(b.name,'ko'));
    const skillRow=(id='',level=1)=>`<div class="edit-skill"><select class="charm-skill" aria-label="호석 스킬">${option('','스킬 선택',id)}${skills.map(s=>option(s.id,s.name,id)).join('')}</select><input type="number" class="charm-skill-level" aria-label="호석 스킬 레벨" min="1" max="${skills.find(s=>s.id===id)?.maxLevel||5}" value="${level}"><button type="button" class="remove-charm-skill" aria-label="호석 스킬 삭제">×</button></div>`;
    host.innerHTML=`<button type="button" class="icon-button close" id="close-charm-editor" aria-label="닫기">×</button><h2>호석 ${source.id&&!copy?'수정':'등록'}</h2><p class="hint">호석의 레어도, 스킬과 슬롯을 게임에 표시된 대로 입력하세요.</p><form id="charm-form" autocomplete="off"><div class="form-grid"><label class="field full">호석 이름<input id="charm-name" name="charm-name" autocomplete="off" required maxlength="80" value="${esc(source.name)}" placeholder="예: 건랜스용 번영의 호석"></label><label class="field">호석 종류<select id="charm-type">${option('appraised','감정 호석',C.typeOf(source,db))}${option('crafted','제작 호석',C.typeOf(source,db))}</select></label><label class="field"><span class="row">레어도<span id="charm-rarity-alert" class="charm-warning-icon" hidden aria-label="레어도와 입력 내용 확인 필요">!</span></span><select id="charm-rarity" required aria-describedby="charm-check"></select></label></div><div id="charm-check" aria-live="polite"></div><label class="field">호석 메모<input id="charm-notes" name="charm-notes" maxlength="200" value="${esc(source.notes)}" placeholder="예: 사용할 세팅, 획득한 퀘스트"></label><div class="form-section"><h3>장식주 슬롯</h3>${Array.from({length:3},(_,i)=>`<div class="edit-slot"><small>${i+1}번</small><select class="charm-slot-kind" aria-label="${i+1}번 호석 슬롯 종류">${option('armor','방어구용',source.slots?.[i]?.kind||'armor')}${option('weapon','무기용',source.slots?.[i]?.kind||'armor')}</select><select class="charm-slot-level" aria-label="${i+1}번 호석 슬롯 크기">${[0,1,2,3].map(n=>option(n,n?'Lv '+n:'없음',source.slots?.[i]?.level||0)).join('')}</select></div>`).join('')}<p class="hint">무기용·방어구용 구분과 슬롯 크기를 함께 확인하세요.</p></div><div class="form-section"><div class="row between"><h3>호석 스킬</h3><button type="button" id="add-charm-skill">＋ 스킬</button></div><div id="charm-skills">${Object.keys(source.skills||{}).length?Object.entries(source.skills).map(([id,n])=>skillRow(id,n)).join(''):skillRow()}</div></div><p id="charm-error" class="warning-text hint" role="alert"></p><div class="form-actions"><button type="button" id="cancel-charm-editor">취소</button><button type="submit" class="primary">호석 저장</button></div></form>`;
    function rarityOptions(current){const list=$('#charm-type').value==='appraised'?[5,6,7,8]:[2,3,4,5,6,7,8];$('#charm-rarity').innerHTML=option('','레어도 선택',current)+list.map(r=>option(r,'레어도 '+r+($('#charm-type').value==='appraised'?' · '+C.NAMES[r]:''),current)).join('');}
    function readDraft(){const entries=$$('.charm-skill').filter(s=>s.value).map(s=>[s.value,+s.parentElement.querySelector('input').value]);return {...source,name:$('#charm-name').value.trim(),charmType:$('#charm-type').value,category:$('#charm-type').value==='appraised'?'감정 호석':'제작 호석',random:$('#charm-type').value==='appraised',rarity:$('#charm-rarity').value?+$('#charm-rarity').value:undefined,notes:$('#charm-notes').value.trim(),skills:Object.fromEntries(entries),tags:{},slots:$$('.edit-slot').map(row=>({kind:row.querySelector('.charm-slot-kind').value,level:+row.querySelector('.charm-slot-level').value})).filter(s=>s.level),entries};}
    function updateCheck(){const draft=readDraft(),result=C.check(draft,db),duplicate=new Set(draft.entries.map(([id])=>id)).size!==draft.entries.length;if(duplicate)result.issues.unshift({field:'skills',message:'같은 스킬이 여러 줄에 입력되어 있습니다. 스킬별로 한 줄에 입력하세요.'});const warning=result.issues.length>0;$('#charm-rarity-alert').hidden=!warning;$('#charm-rarity-alert').title=result.issues.map(i=>i.message).join('\n');$('#charm-rarity').setAttribute('aria-invalid',String(warning));$('#charm-check').className=warning?'charm-warning':'hint';$('#charm-check').innerHTML=warning?`<strong><span aria-hidden="true">!</span> 레어도와 입력 내용을 확인하세요</strong><ul>${result.issues.map(i=>`<li>${esc(i.message)}</li>`).join('')}</ul>${result.alternatives.length?`<p>현재 내용이 가능한 레어도: ${result.alternatives.join(', ')}</p>`:''}<p class="hint">입력을 계속하거나 그대로 저장할 수 있습니다.</p>`:!draft.rarity?'게임에 표시된 레어도를 선택하세요.':result.status==='incomplete'?'스킬을 입력하면 레어도와 슬롯 구성을 함께 확인합니다.':'';}
    function bindRows(){for(const button of $$('.remove-charm-skill'))button.onclick=()=>{button.parentElement.remove();updateCheck();};for(const select of $$('.charm-skill'))select.onchange=()=>{const level=select.parentElement.querySelector('input');level.max=skills.find(s=>s.id===select.value)?.maxLevel||5;level.value=Math.min(+level.value,+level.max);updateCheck();};for(const input of $$('.charm-skill-level'))input.oninput=updateCheck;}
    $('#charm-type').onchange=()=>{rarityOptions($('#charm-rarity').value);updateCheck();};$('#charm-rarity').onchange=updateCheck;for(const input of $$('.charm-slot-kind,.charm-slot-level'))input.onchange=updateCheck;
    $('#add-charm-skill').onclick=()=>{if($$('.charm-skill').length<10){$('#charm-skills').insertAdjacentHTML('beforeend',skillRow());bindRows();updateCheck();}};
    const close=()=>dialog.close();$('#close-charm-editor').onclick=close;$('#cancel-charm-editor').onclick=close;
    $('#charm-form').onsubmit=e=>{e.preventDefault();try{const draft=readDraft();if(!draft.name)throw Error('호석 이름을 입력하세요.');if(!draft.rarity)throw Error('레어도를 선택하세요.');if(new Set(draft.entries.map(([id])=>id)).size!==draft.entries.length)throw Error('같은 스킬을 중복 입력할 수 없습니다.');for(const [id,n]of draft.entries)if(!Number.isInteger(n)||n<1||n>skills.find(s=>s.id===id)?.maxLevel)throw Error('스킬 레벨을 확인하세요.');delete draft.entries;onSave(draft);close();}catch(error){$('#charm-error').textContent=error.message;}};
    rarityOptions(source.rarity);bindRows();updateCheck();dialog.classList.add('charm-dialog');dialog.addEventListener('close',()=>dialog.classList.remove('charm-dialog'),{once:true});dialog.showModal();$('#charm-name').focus();
  }
  root.WildsCharmEditor={open};
})(globalThis);
